import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_tables(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint") or os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = config.get("api_key") or os.environ["AZURE_FORM_RECOGNIZER_KEY"]
    model_id = config.get("model_id", "prebuilt-layout")
    client = DocumentAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))
    if isinstance(payload, (bytes, bytearray)):
        poller = client.begin_analyze_document(model_id, document=payload)
    elif hasattr(payload, "read"):
        poller = client.begin_analyze_document(model_id, document=payload)
    elif isinstance(payload, str):
        if payload.startswith("http://") or payload.startswith("https://"):
            poller = client.begin_analyze_document_from_url(model_id, payload)
        else:
            with open(payload, "rb") as f:
                poller = client.begin_analyze_document(model_id, document=f)
    else:
        raise TypeError("payload must be bytes, a file-like object, a local file path, or a URL")
    analysis = poller.result()
    result = []
    for table_idx, table in enumerate(getattr(analysis, "tables", []) or []):
        rows = {}
        cells = []
        for cell in table.cells:
            cell_data = {
                "table_index": table_idx,
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "row_span": getattr(cell, "row_span", 1) or 1,
                "column_span": getattr(cell, "column_span", 1) or 1,
                "kind": getattr(cell, "kind", None),
                "content": cell.content,
                "bounding_regions": [
                    {
                        "page_number": br.page_number,
                        "polygon": list(br.polygon) if br.polygon else None,
                    }
                    for br in (getattr(cell, "bounding_regions", None) or [])
                ],
            }
            cells.append(cell_data)
            rows.setdefault(cell.row_index, []).append(cell_data)
        ordered_rows = [
            {
                "row_index": row_index,
                "cells": sorted(
                    row_cells,
                    key=lambda c: (c["column_index"], c["row_span"], c["column_span"]),
                ),
            }
            for row_index, row_cells in sorted(rows.items(), key=lambda item: item[0])
        ]
        result.append(
            {
                "table_index": table_idx,
                "row_count": table.row_count,
                "column_count": table.column_count,
                "cells": sorted(cells, key=lambda c: (c["row_index"], c["column_index"])),
                "rows": ordered_rows,
                "bounding_regions": [
                    {
                        "page_number": br.page_number,
                        "polygon": list(br.polygon) if br.polygon else None,
                    }
                    for br in (getattr(table, "bounding_regions", None) or [])
                ],
            }
        )
    return result
